SELECT id, symbol, status, close_reason, entry_price, stop_loss, take_profit, ROUND((entry_price - stop_loss) / entry_price * 100, 4) AS sl_pct, ROUND((take_profit - entry_price) / entry_price * 100, 4) AS tp_pct, ROUND((take_profit - entry_price) / NULLIF(entry_price - stop_loss, 0), 3) AS planned_rr, realized_pnl, opened_at, closed_at FROM crypto_ai.paper_position WHERE opened_at BETWEEN '2026-10-11 00:00:00' AND '2026-10-15 23:59:59' ORDER BY id LIMIT 200;